(async()=>{const id=document.body.dataset.productId;const products=await(await fetch('/data/catalog.json')).json();const p=products.find(p=>p.id===id);if(!p)return;if(location.pathname.startsWith('/p/')&&matchMedia('(max-width:991px)').matches&&p.mobileOriginalPage){location.replace('/pm/'+id+'.html');return}let choices={};let currentPrice=p.price;const main=document.querySelector('main');let quantity=1;const {selectedPrice}=await import('/sale-pricing.js');
const {sizeProductId,productPage,updatePriceText}=await import('/product-variants.js');
main.querySelectorAll('.page-changer__page-button').forEach(button=>{
 const target=products.find(product=>product.id===sizeProductId(id,button.textContent));
 if(target)button.onclick=()=>{if(target.id!==id)location.assign(productPage(target,matchMedia('(max-width:991px)').matches))};
});
function refreshPrice(){currentPrice=selectedPrice(p,sourceGroups,choices);main.querySelectorAll('[aria-label="Preço à vista"],.MobQuickBuy__por').forEach(node=>updatePriceText(node,currentPrice));
 // Captured installment prices describe the initial variant only.
 main.querySelectorAll('[aria-label="Preço parcelado"]').forEach(node=>{node.hidden=currentPrice!==p.price;node.style.setProperty('display',currentPrice!==p.price?'none':'','important')});
}
function syncChoice(name,label){for(const group of main.querySelectorAll('[role=listbox],[role=radiogroup]')){if(group.getAttribute('aria-label')!==name)continue;const isList=group.getAttribute('role')==='listbox';for(const option of group.querySelectorAll('[role=option],[role=radio]')){const text=option.querySelector('.opcao-nome')?.textContent.trim()||option.getAttribute('aria-label')||option.textContent.trim();option.setAttribute(isList?'aria-selected':'aria-checked',String(text===label));option.classList.toggle('active',text===label);option.classList.toggle('weightCards__card--selected',text===label&&option.classList.contains('weightCards__card'));if(option.hasAttribute('aria-pressed'))option.setAttribute('aria-pressed',String(text===label));const input=option.querySelector('input[type=radio]');if(input)input.checked=text===label}if(isList){group.hidden=true;const trigger=group.parentElement.querySelector('[aria-haspopup=listbox]');if(trigger){trigger.textContent=label;trigger.setAttribute('aria-expanded','false')}}}}
let variants=null;try{const response=await fetch('/data/variants/'+id+'.json');if(response.ok)variants=await response.json()}catch{}const sourceGroups=variants?.groups||p.groups||[];

// Older product templates use role=button for their radio choices.
main.querySelectorAll('.attrSimples__container[role=group]').forEach(group=>{
 const data=sourceGroups.find(g=>g.name===group.getAttribute('aria-label'));
 if(!data)return;
 group.setAttribute('role','radiogroup');
 group.querySelectorAll('.attrSimples__button').forEach(item=>{
  const option=data.options.find(o=>o.name===item.getAttribute('aria-label'));
  item.setAttribute('role','radio');item.setAttribute('aria-checked',String(!!option?.selected));item.setAttribute('aria-disabled',String(!option||!!option.disabled));
 });
});
main.querySelectorAll('[aria-haspopup="listbox"]').forEach((control,index)=>{if(String(control.className).includes('ts-'))return;const holder=control.parentElement;let group=holder.querySelector('[role="listbox"]');if(group)return;const label=control.textContent.trim();const data=sourceGroups.find(g=>g.name===label)||sourceGroups[index]||(sourceGroups.length===1?sourceGroups[0]:null);if(!data?.options?.length){control.dataset.unresolvedVariant='true';return}group=document.createElement('ul');group.setAttribute('role','listbox');group.setAttribute('aria-label',data.name);data.options.forEach(option=>{const li=document.createElement('li');li.className='opcao-item';li.setAttribute('role','option');li.tabIndex=0;li.setAttribute('aria-disabled',String(!!option.disabled));li.setAttribute('aria-selected',String(!!option.selected));li.textContent=option.name;if(option.text)li.dataset.optionText=option.text;group.append(li)});holder.append(group);});
document.querySelectorAll('main [role="radiogroup"],main [role="listbox"]').forEach((group,index)=>{if(group.id.startsWith('ts-'))return;const name=group.getAttribute('aria-label')||'Opção '+(index+1);const list=group.getAttribute('role')==='listbox';let button=list?group.parentElement.querySelector('[aria-haspopup="listbox"]'):null;if(list){group.dataset.localList='true';group.hidden=true;if(button){button.setAttribute('aria-expanded','false');button.onclick=()=>{group.hidden=!group.hidden;button.setAttribute('aria-expanded',String(!group.hidden))}}}for(const item of group.querySelectorAll('[role="option"],[role="radio"]')){const label=item.querySelector('.opcao-nome')?.textContent.trim()||item.getAttribute('aria-label')||item.textContent.trim();if(item.getAttribute('aria-selected')==='true'||item.getAttribute('aria-checked')==='true')choices[name]=label;item.onclick=()=>{if(item.getAttribute('aria-disabled')==='true'||sourceGroups.find(g=>g.name===name)?.options.find(o=>o.name===label)?.disabled)return;choices[name]=label;syncChoice(name,label);const heading=group.closest('.attrUnico,.attrSimples')?.querySelector('.flavorSelector__hover b,.attrSimples__hoverAttr b,strong');if(heading)heading.textContent=label;group.querySelectorAll('[role="option"],[role="radio"]').forEach(e=>{e.setAttribute(list?'aria-selected':'aria-checked',String(e===item));e.classList.toggle('active',e===item)});if(button){button.textContent=label;button.setAttribute('aria-expanded','false');group.hidden=true}refreshPrice();document.querySelector('.local-selection-error')?.remove()};item.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();item.click()}}}});
refreshPrice();
main.querySelectorAll('button,input[type=button]').forEach(b=>{if(!/^comprar$/i.test((b.textContent||b.value||'').trim()))return;b.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();const groups=[...main.querySelectorAll('[role="radiogroup"],[role="listbox"]')].filter(g=>!g.id.startsWith('ts-'));const missing=groups.find((g,i)=>!choices[g.getAttribute('aria-label')||'Opção '+(i+1)]);const unresolved=main.querySelector('[data-unresolved-variant]');if(missing||unresolved||!currentPrice){let err=document.querySelector('.local-selection-error');if(!err){err=document.createElement('p');err.className='local-selection-error';err.setAttribute('role','alert');b.before(err)}err.textContent=unresolved?'As opções deste produto ainda estão sendo conferidas.':missing?'Selecione a variação do produto antes de comprar.':'Preço ainda não confirmado.';err.scrollIntoView({block:'center',behavior:'smooth'});return}const q=main.querySelector('input[type=number]');const count=Math.max(1,Math.min(99,Number(q?.value)||quantity));if(window.GrowthStore)window.GrowthStore.add({id,options:{...choices},quantity:count,price:currentPrice,image:p.images[0]});},true)});

main.querySelectorAll('button[aria-label="Aumentar quantidade"],button[aria-label="Diminuir quantidade"]').forEach(b=>b.onclick=()=>{quantity=Math.max(1,Math.min(99,quantity+(b.getAttribute('aria-label').startsWith('Aumentar')?1:-1)));const group=b.parentElement;const label=[...group.children].find(e=>e.tagName!=='BUTTON');if(label)label.textContent=quantity;group.querySelectorAll('button').forEach(e=>e.disabled=e.getAttribute('aria-label')?.startsWith('Diminuir')&&quantity===1)});
const gallery=main.querySelector('.gallery');if(gallery&&!gallery.querySelector('img')){const frame=gallery.querySelector('.gallery__main .swiper-wrapper');if(frame){for(const src of p.images.slice(0,8)){const slide=document.createElement('div');slide.className='gallery__main-slide';const img=document.createElement('img');img.src=src;img.alt=p.name;img.style.cssText='width:100%;height:480px;object-fit:contain';slide.append(img);frame.append(slide)}}}
const slides=[...main.querySelectorAll('.gallery__main-slide')];let imageIndex=0;function showImage(n){imageIndex=(n+slides.length)%slides.length;slides.forEach((s,i)=>{s.style.display=i===imageIndex?'block':'none';s.style.width='100%'});const track=slides[0]?.parentElement;if(track)track.style.transform='none'}if(slides.length){main.querySelectorAll('button[aria-label="Imagem anterior"],button[aria-label="Próxima imagem"]').forEach(b=>{b.disabled=false;b.removeAttribute('aria-disabled')});showImage(0);main.querySelectorAll('.gallery__thumb-slide').forEach((b,i)=>b.onclick=()=>showImage(i));main.querySelectorAll('button[aria-label="Imagem anterior"],button[aria-label="Próxima imagem"]').forEach(b=>b.onclick=()=>showImage(imageIndex+(b.getAttribute('aria-label')==='Imagem anterior'?-1:1)))}
main.querySelectorAll('button[aria-controls]').forEach(b=>{const panel=document.getElementById(b.getAttribute('aria-controls'));if(panel&&b.hasAttribute('aria-expanded'))b.onclick=()=>{const expanded=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(expanded));panel.hidden=!expanded;panel.style.display=expanded?'block':'none'}});
const photoModal=main.querySelector('#myModal');
if(photoModal){
 const photos=[...photoModal.querySelectorAll('.mySlides .modal-image')].map(img=>({src:img.getAttribute('src'),alt:img.alt||p.name})).filter(img=>img.src);
 photoModal.remove();
 if(photos.length){
 const viewer=document.createElement('dialog');viewer.className='local-photo-gallery';viewer.setAttribute('aria-label','Galeria de imagens do produto');
 viewer.innerHTML='<button type="button" class="photo-close" aria-label="Fechar galeria">×</button><img class="photo-image" alt=""><button type="button" class="photo-prev" aria-label="Imagem anterior">‹</button><button type="button" class="photo-next" aria-label="Próxima imagem">›</button><output class="photo-count" aria-live="polite"></output>';
 document.body.append(viewer);const image=viewer.querySelector('img');let index=0,trigger=null,previousOverflow='';
 const show=n=>{index=(n+photos.length)%photos.length;image.src=photos[index].src;image.alt=photos[index].alt;viewer.querySelector('output').textContent=(index+1)+' / '+photos.length};
 const open=(n,button)=>{trigger=button;show(n);previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';viewer.showModal();viewer.querySelector('.photo-close').focus({preventScroll:true})};
 viewer.addEventListener('close',()=>{document.body.style.overflow=previousOverflow;trigger?.focus({preventScroll:true})});
 viewer.querySelector('.photo-close').onclick=()=>viewer.close();
 for(const [selector,delta] of [['.photo-prev',-1],['.photo-next',1]]){const button=viewer.querySelector(selector);button.hidden=photos.length<2;button.onclick=e=>{e.preventDefault();e.stopPropagation();show(index+delta)}}
 viewer.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();show(index+(e.key==='ArrowLeft'?-1:1))}});
 main.querySelectorAll('.ver-mais-fotos').forEach(button=>button.onclick=()=>open(0,button));
 main.querySelectorAll('.imagem-produto-default').forEach((img,i)=>{img.tabIndex=0;img.setAttribute('role','button');img.setAttribute('aria-label','Ampliar foto '+(i+1)+' do produto');img.onclick=()=>open(i,img);img.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open(i,img)}}});
 }
}
main.querySelectorAll('button[aria-label="Fechar vídeo informativo"]').forEach(b=>b.onclick=()=>b.parentElement.remove());
main.querySelectorAll('button').forEach(b=>{if(/^(veja a tabela nutricional)$/i.test(b.textContent.trim()))b.onclick=()=>document.getElementById('tabela-nutricional')?.scrollIntoView({behavior:'smooth'})});
document.addEventListener('submit',e=>{e.preventDefault()},true);
})();
